package org.eclipse.rdf4j.query.algebra.helpers;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Graph;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class ValuedVariableObservationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI G = VF.createIRI("urn:valued-variable:graph");

	@Test
	void valuedPublicGraphSelectorStillObservesItsCallerBinding() {
		assertObserved(new Graph(Var.of("graph", G, false, false), new SingletonSet()));
	}

	@Test
	void valuedInheritedStatementContextStillObservesItsCallerBinding() {
		StatementPattern pattern = statement(Var.of("graph", G, false, false));
		pattern.setContextBindingOriginInherited(true);
		assertObserved(pattern);
	}

	@Test
	void trueConstantsDoNotAcquireCallerBindingDependencies() {
		for (TupleExpr body : List.of(new Graph(Var.of("graph", G, false, true), new SingletonSet()),
				statement(Var.of("graph", G, false, true)))) {
			TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(new Exists(body));
			assertThat(observed.known()).isTrue();
			assertThat(observed.names()).isEmpty();
			assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of())).isTrue();
		}
	}

	private static void assertObserved(TupleExpr body) {
		TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(new Exists(body));
		assertThat(!observed.known() || observed.names().contains("graph"))
				.as("an optimizer value does not remove a public variable's caller compatibility check")
				.isTrue();
		assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of())).isFalse();
	}

	private static StatementPattern statement(Var context) {
		return new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("subject", VF.createIRI("urn:valued-variable:s"), false, true),
				Var.of("predicate", VF.createIRI("urn:valued-variable:p"), false, true),
				Var.of("object", VF.createIRI("urn:valued-variable:o"), false, true), context);
	}
}
